"""W2-86: namespaces per tracked path and the embedded verdict, new map against the base's."""
import subprocess
import sys
from collections import Counter

import yaml

from gov.secrets import _matches

BASE = "9dc5288161c4"
MAP = "governance/project/path-map.yaml"


def namespaces(text):
    return yaml.safe_load(text)["namespaces"]


def hits(spaces, rel):
    return [name for name, entry in spaces.items() if any(_matches(rel, p) for p in entry["paths"])]


def verdict(spaces, rel):
    pol = [spaces[n].get("embedding_policy") for n in hits(spaces, rel)]
    return bool(pol) and all(p == "embedded" for p in pol)


def group(rel):
    k = "template/governance/kernel/"
    if rel.startswith(k + "roles/"):
        return "roles"
    if rel.startswith(k + "hooks/"):
        return "hooks"
    if rel == k + "skills/superpowers/vendored.yaml":
        return "vendored.yaml"
    if rel.startswith((k + "vendor/", k + "skills/superpowers/", k + "bin/")):
        return "vendored set"
    if rel.startswith(k + "skills/") and rel.endswith("/SKILL.md"):
        return "kernel skills"
    if rel.startswith("template/.rulesync/"):
        return ".rulesync"
    return "other template"


new = namespaces(open(MAP).read())
base = namespaces(subprocess.run(["git", "show", f"{BASE}:{MAP}"], capture_output=True, text=True, check=True).stdout)
files = subprocess.run(["git", "ls-files"], capture_output=True, text=True, check=True).stdout.split("\n")
files = [f for f in files if f]
values = sorted({str(e.get("embedding_policy")) for e in new.values()})
print("policy values:", values)
bad, changed, groups = [], [], Counter()
for rel in files:
    if rel.startswith("template/"):
        h = hits(new, rel)
        if len(h) != 1:
            bad.append((rel, h))
        groups[(group(rel), verdict(new, rel))] += 1
    elif verdict(new, rel) != verdict(base, rel):
        changed.append(rel)
print("tracked files:", len(files), "under template/:", sum(1 for f in files if f.startswith("template/")))
print("template paths in zero or two+ namespaces:", len(bad), bad[:10])
for (g, v), n in sorted(groups.items()):
    print(f"  {g:15s} embedded={v}: {n}")
print("verdict changes outside template/:", len(changed), changed[:10])
sys.exit(1 if bad or changed or values != ["embedded", "not embedded"] else 0)
